class Solution:
    def minimumRemovals(self, nums, target):
        M = 16385
        NEG = float('-inf')
        dp = [NEG] * M
        dp[0] = 0
        for x in nums:
            nd = dp[:]
            for y in range(M):
                if dp[y] != NEG:
                    z = y ^ x
                    if dp[y] + 1 > nd[z]:
                        nd[z] = dp[y] + 1
            dp = nd
        return len(nums) - dp[target] if dp[target] != NEG else -1

