class Solution {
public:
    int minimumRemovals(vector<int>& nums, int target) {
        const int M = 16385, NEG = INT_MIN / 2;
        vector<int> dp(M, NEG);
        dp[0] = 0;
        for (int x : nums) {
            vector<int> nd = dp;
            for (int y = 0; y < M; y++)
                if (dp[y] != NEG) {
                    int z = y ^ x;
                    if (dp[y] + 1 > nd[z]) nd[z] = dp[y] + 1;
                }
            dp = nd;
        }
        return dp[target] == NEG ? -1 : (int)nums.size() - dp[target];
    }
};

