class Solution {
    public int minimumRemovals(int[] nums, int target) {
        final int M = 16385, NEG = Integer.MIN_VALUE / 2;
        int[] dp = new int[M];
        Arrays.fill(dp, NEG);
        dp[0] = 0;
        for (int x : nums) {
            int[] nd = dp.clone();
            for (int y = 0; y < M; y++)
                if (dp[y] != NEG) {
                    int z = y ^ x;
                    if (dp[y] + 1 > nd[z]) nd[z] = dp[y] + 1;
                }
            dp = nd;
        }
        return dp[target] == NEG ? -1 : nums.length - dp[target];
    }
}

