var minimumRemovals = function(nums, target) {
    const M = 16385, NEG = -1e9;
    let dp = new Array(M).fill(NEG);
    dp[0] = 0;
    for (const x of nums) {
        const nd = dp.slice();
        for (let y = 0; y < M; y++)
            if (dp[y] !== NEG) {
                const z = y ^ x;
                if (dp[y] + 1 > nd[z]) nd[z] = dp[y] + 1;
            }
        dp = nd;
    }
    return dp[target] === NEG ? -1 : nums.length - dp[target];
};
